    public Object calculate(String formula, Map<String, Object> context) throws ScriptException {
        // Replace variables with their values from context
        String processedFormula = replaceVariables(formula, context);
        // Evaluate the expression safely
        return evaluateExpression(processedFormula);
    }

    /**
     * Replaces variable names in the formula with their actual values from the context.
     */
    private String replaceVariables(String formula, Map<String, Object> context) {
        if (context == null) {
            return formula;
        }
        String result = formula;
        for (Map.Entry<String, Object> entry : context.entrySet()) {
            String key = entry.getKey();
