    /**
     * Evaluates a mathematical expression safely using a simple recursive descent parser.
     * Supports: +, -, *, /, %, ^, parentheses, and decimal numbers.
     * Also supports conditional logic (ternary operator) and string literals.
     */
    private Object evaluateExpression(String expression) throws ScriptException {
        // Remove whitespace
        expression = expression.trim();
        if (expression.isEmpty()) {
            throw new ScriptException("Empty expression");
        }

        // Handle string literals (enclosed in single quotes)
        if (expression.startsWith("'") && expression.endsWith("'") && expression.length() >= 2) {
            return expression.substring(1, expression.length() - 1);
        }

        // Handle conditional (ternary) operator: condition ? value1 : value2
        int questionPos = findTopLevelOperator(expression, '?');
        if (questionPos >= 0) {
            String condition = expression.substring(0, questionPos).trim();
            int colonPos = findMatchingColon(expression, questionPos);
            if (colonPos < 0) {
                throw new ScriptException("Missing colon in ternary expression");
            }
            String trueValue = expression.substring(questionPos + 1, colonPos).trim();
            String falseValue = expression.substring(colonPos + 1).trim();

            Object conditionResult = evaluateExpression(condition);
            boolean conditionBool;
            if (conditionResult instanceof Boolean) {
                conditionBool = (Boolean) conditionResult;
            } else if (conditionResult instanceof Number) {
                conditionBool = ((Number) conditionResult).doubleValue() != 0;
            } else {
                throw new ScriptException("Condition must evaluate to boolean or numeric value");
            }

            return conditionBool ? evaluateExpression(trueValue) : evaluateExpression(falseValue);
        }

        // Handle comparison operators: >, <, >=, <=, ==, !=
        int compPos = findComparisonOperator(expression);
        if (compPos >= 0) {
            String op = extractComparisonOperator(expression, compPos);
            String leftExpr = expression.substring(0, compPos).trim();
            String rightExpr = expression.substring(compPos + op.length()).trim();

            Object leftVal = evaluateExpression(leftExpr);
            Object rightVal = evaluateExpression(rightExpr);

            double leftNum, rightNum;
            try {
                leftNum = Double.parseDouble(leftVal.toString());
                rightNum = Double.parseDouble(rightVal.toString());
            } catch (NumberFormatException e) {
                // Compare as strings if not numbers
                String leftStr = leftVal.toString();
                String rightStr = rightVal.toString();
                int cmp = leftStr.compareTo(rightStr);
                switch (op) {
                    case "==": return cmp == 0;
                    case "!=": return cmp != 0;
                    case ">": return cmp > 0;
                    case "<": return cmp < 0;
                    case ">=": return cmp >= 0;
                    case "<=": return cmp <= 0;
                    default: throw new ScriptException("Unknown comparison operator: " + op);
                }
            }

            switch (op) {
                case "==": return leftNum == rightNum;
                case "!=": return leftNum != rightNum;
                case ">": return leftNum > rightNum;
                case "<": return leftNum < rightNum;
                case ">=": return leftNum >= rightNum;
                case "<=": return leftNum <= rightNum;
                default: throw new ScriptException("Unknown comparison operator: " + op);
            }
        }

        // Handle logical operators: &&, ||
        int logPos = findLogicalOperator(expression);
        if (logPos >= 0) {
            String op = extractLogicalOperator(expression, logPos);
            String leftExpr = expression.substring(0, logPos).trim();
            String rightExpr = expression.substring(logPos + op.length()).trim();

            Object leftVal = evaluateExpression(leftExpr);
            boolean leftBool;
            if (leftVal instanceof Boolean) {
                leftBool = (Boolean) leftVal;
            } else if (leftVal instanceof Number) {
                leftBool = ((Number) leftVal).doubleValue() != 0;
            } else {
                throw new ScriptException("Logical operator requires boolean or numeric operands");
            }

            if (op.equals("&&") && !leftBool) {
                return false;
            }
            if (op.equals("||") && leftBool) {
                return true;
            }

            Object rightVal = evaluateExpression(rightExpr);
            boolean rightBool;
            if (rightVal instanceof Boolean) {
                rightBool = (Boolean) rightVal;
            } else if (rightVal instanceof Number) {
                rightBool = ((Number) rightVal).doubleValue() != 0;
            } else {
                throw new ScriptException("Logical operator requires boolean or numeric operands");
            }

            return op.equals("&&") ? (leftBool && rightBool) : (leftBool || rightBool);
        }

        // Handle arithmetic operators: +, -, *, /, %, ^
        // Process in order of precedence: ^ (right to left), *, /, % (left to right), +, - (left to right)
        // First find top-level + or - (outside parentheses)
        int addSubPos = findTopLevelAddSub(expression);
        if (addSubPos >= 0) {
            char op = expression.charAt(addSubPos);
            String leftExpr = expression.substring(0, addSubPos).trim();
            String rightExpr = expression.substring(addSubPos + 1).trim();

            Object leftVal = evaluateExpression(leftExpr);
            Object rightVal = evaluateExpression(rightExpr);

            double leftNum = toDouble(leftVal);
            double rightNum = toDouble(rightVal);

            double result;
            if (op == '+') {
                result = leftNum + rightNum;
            } else {
                result = leftNum - rightNum;
            }
            return result;
        }

        // Find top-level *, /, % (outside parentheses)
        int mulDivPos = findTopLevelMulDiv(expression);
        if (mulDivPos >= 0) {
            char op = expression.charAt(mulDivPos);
            String leftExpr = expression.substring(0, mulDivPos).trim();
            String rightExpr = expression.substring(mulDivPos + 1).trim();

            Object leftVal = evaluateExpression(leftExpr);
            Object rightVal = evaluateExpression(rightExpr);

            double leftNum = toDouble(leftVal);
            double rightNum = toDouble(rightVal);

            double result;
