                case '*':
                    result = leftNum * rightNum;
                    break;
                case '/':
                    if (rightNum == 0) {
                        throw new ScriptException("Division by zero");
                    }
                    result = leftNum / rightNum;
                    break;
                case '%':
                    result = leftNum % rightNum;
                    break;
                default:
                    throw new ScriptException("Unknown operator: " + op);
            }
            return result;
        }

        // Find top-level ^ (exponentiation, right to left)
        int powPos = findTopLevelPow(expression);
        if (powPos >= 0) {
            String leftExpr = expression.substring(0, powPos).trim();
            String rightExpr = expression.substring(powPos + 1).trim();

            Object leftVal = evaluateExpression(leftExpr);
            Object rightVal = evaluateExpression(rightExpr);

            double leftNum = toDouble(leftVal);
            double rightNum = toDouble(rightVal);

            return Math.pow(leftNum, rightNum);
        }

        // Handle parentheses
        if (expression.startsWith("(") && expression.endsWith(")")) {
            // Check if it's a fully parenthesized expression
            int depth = 0;
            boolean fullyParenthesized = true;
            for (int i = 0; i < expression.length() - 1; i++) {
                char c = expression.charAt(i);
                if (c == '(') depth++;
                else if (c == ')') depth--;
                if (depth == 0) {
                    fullyParenthesized = false;
                    break;
                }
            }
            if (fullyParenthesized) {
                return evaluateExpression(expression.substring(1, expression.length() - 1));
            }
        }

        // If no operators found, try to parse as number or boolean
        if (expression.equalsIgnoreCase("true")) return true;
        if (expression.equalsIgnoreCase("false")) return false;

