    /**
     * Finds the position of a top-level + or - operator (not inside parentheses or quotes).
     */
    private int findTopLevelAddSub(String expr) {
        int depth = 0;
        boolean inQuote = false;
        for (int i = expr.length() - 1; i >= 0; i--) {
            char c = expr.charAt(i);
            if (c == '\'') {
                inQuote = !inQuote;
            } else if (!inQuote) {
                if (c == ')') depth++;
                else if (c == '(') depth--;
                else if (depth == 0 && (c == '+' || c == '-')) {
