        boolean inQuote = false;
        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == '\'') {
                inQuote = !inQuote;
            } else if (!inQuote) {
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (depth == 0 && (c == '*' || c == '/' || c == '%')) {
                    return i;
                }
            }
        }
        return -1;
    }

    /**
     * Finds the position of a top-level ^ operator (not inside parentheses or quotes).
     */
    private int findTopLevelPow(String expr) {
        int depth = 0;
        boolean inQuote = false;
        for (int i = expr.length() - 1; i >= 0; i--) {
            char c = expr.charAt(i);
            if (c == '\'') {
                inQuote = !inQuote;
            } else if (!inQuote) {
                if (c == ')') depth++;
                else if (c == '(') depth--;
                else if (depth == 0 && c == '^') {
                    return i;
                }
            }
        }
        return -1;
    }

    private boolean isOperator(char c) {
        return c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '^';
    }

    /**
     * Finds the position of a top-level operator (not inside parentheses or quotes).
     */
    private int findTopLevelOperator(String expr, char op) {
        int depth = 0;
        boolean inQuote = false;
        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == '\'') {
                inQuote = !inQuote;
            } else if (!inQuote) {
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (depth == 0 && c == op) {
                    return i;
                }
            }
        }
        return -1;
    }

    /**
     * Finds the matching colon for a ternary operator.
     */
    private int findMatchingColon(String expr, int questionPos) {
        int depth = 0;
        boolean inQuote = false;
        for (int i = questionPos + 1; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == '\'') {
                inQuote = !inQuote;
            } else if (!inQuote) {
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (depth == 0 && c == ':') {
                    return i;
                }
            }
        }
        return -1;
    }

    /**
     * Finds the position of a comparison operator (>, <, >=, <=, ==, !=) at top level.
     */
    private int findComparisonOperator(String expr) {
        int depth = 0;
        boolean inQuote = false;
        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (c == '\'') {
                inQuote = !inQuote;
            } else if (!inQuote) {
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (depth == 0) {
                    if (i + 1 < expr.length()) {
                        String twoChars = expr.substring(i, i + 2);
                        if (twoChars.equals(">=") || twoChars.equals("<=") || 
                            twoChars.equals("==") || twoChars.equals("!=")) {
                            return i;
                        }
                    }
                    if (c == '>' || c == '<') {
                        return i;
                    }
                }
            }
        }
        return -1;
    }

    /**
     * Extracts the comparison operator at the given position.
     */
    private String extractComparisonOperator(String expr, int pos) {
        if (pos + 1 < expr.length()) {
            String twoChars = expr.substring(pos, pos + 2);
            if (twoChars.equals(">=") || twoChars.equals("<=") || 
                twoChars.equals("==") || twoChars.equals("!=")) {
                return twoChars;
            }
        }
        return String.valueOf(expr.charAt(pos));
    }

    /**
     * Finds the position of a logical operator (&&, ||) at top level.
     */
    private int findLogicalOperator(String expr) {
        int depth = 0;
        boolean inQuote = false;
        for (int i = 0; i < expr.length() - 1; i++) {
            char c = expr.charAt(i);
            if (c == '\'') {
                inQuote = !inQuote;
            } else if (!inQuote) {
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (depth == 0) {
                    String twoChars = expr.substring(i, i + 2);
                    if (twoChars.equals("&&") || twoChars.equals("||")) {
                        return i;
                    }
                }
            }
        }
        return -1;
    }

    /**
     * Extracts the logical operator at the given position.
     */
    private String extractLogicalOperator(String expr, int pos) {
        return expr.substring(pos, pos + 2);
    }
